<?php
$b=json_body();require_fields($b,['challengeId','code']);
$s=db()->prepare('SELECT * FROM auth_challenges WHERE id=? AND consumed_at IS NULL AND expires_at>NOW()');$s->execute([$b['challengeId']]);$c=$s->fetch();
if(!$c||!password_verify((string)$b['code'],$c['code_hash'])){if($c)db()->prepare('UPDATE auth_challenges SET attempts=attempts+1 WHERE id=?')->execute([$c['id']]);fail(422,'VALIDATION_ERROR','The request contains invalid data.',['code'=>['The code is invalid or expired.']]);}
$field=$c['channel']==='email'?'email':'phone';$q=db()->prepare("SELECT * FROM users WHERE $field=?");$q->execute([$c['destination']]);$u=$q->fetch();
if(!$u){$first=trim((string)($b['firstName']??''));$last=trim((string)($b['lastName']??''));$role=$b['accountRole']??'customer';$errors=[];if($first==='')$errors['firstName']=['Required for registration.'];if($last==='')$errors['lastName']=['Required for registration.'];if(!in_array($role,['customer','partner'],true))$errors['accountRole']=['Expected customer or partner.'];if($errors)fail(422,'VALIDATION_ERROR','The request contains invalid data.',$errors);$uid=uuid();db()->prepare("INSERT INTO users(id,first_name,last_name,$field,role,partner_intent,verified_at,profile_json,preferences_json) VALUES(?,?,?,?,?,?,NOW(),'{}','{}')")->execute([$uid,$first,$last,$c['destination'],$role,$role==='partner']);$q=db()->prepare('SELECT * FROM users WHERE id=?');$q->execute([$uid]);$u=$q->fetch();}
$access=bin2hex(random_bytes(32));$refresh=bin2hex(random_bytes(32));$sid=uuid();db()->beginTransaction();$lock=db()->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$lock->execute([$u['id']]);ensure_active_account((string)$u['id']);db()->prepare('INSERT INTO sessions(id,user_id,access_token_hash,refresh_token_hash,access_expires_at,refresh_expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR),DATE_ADD(NOW(),INTERVAL 30 DAY))')->execute([$sid,$u['id'],hash('sha256',$access),hash('sha256',$refresh)]);db()->prepare('UPDATE auth_challenges SET consumed_at=NOW() WHERE id=?')->execute([$c['id']]);db()->commit();out(session_result($access,$refresh,$u),201);
